part of chem_lab;

class BenchTool {
  // === Realistic capillary action ===
  double capillaryProgress = 0.0;  // 0-1 liquid climb height
  double wetness = 0.0;           // 0-1 how wet the paper is
  double dropFormation = 0.0;     // 0-1 droplets forming after lift
  // Realistic dip animation
  double dipPhase = 0.0;        // 0→1 animation progress
  Offset dipStartPos = Offset.zero;
  Offset dipTargetPos = Offset.zero;
  double colorProgress = 0.0;   // 0-1 color developed on strip
  double shakeAmount = 0.0;     // 0-1 shake animation
  double tilt = 0.0;            // radians - tool tilt during dip
  double dropAnim = 0.0;        // 0-1 liquid drops forming
  double dipProgress = 0.0;
  bool isDipping = false;
  String? dippedEqId;
  Color? resultColor;
  final String id;
  final LabEffect type;
  Offset position;
  String? attachedTo;
  BenchTool({required this.id, required this.type, required this.position, this.attachedTo});
}

